function startVoiceAssistant(){
  if(voiceProcess)return;
  let e=h.join(__dirname,"voice-listener.ps1");
  let catParam=Z||"Bheduu";
  to("[Comnyang] Starting background voice listener for cat:",catParam);
  let settingsFile=nn();
  to("[Comnyang] Voice listener settings file:",settingsFile);
  voiceProcess=Xr("powershell.exe",["-NoProfile","-ExecutionPolicy","Bypass","-File",e,catParam,settingsFile]);
  let t="";
  voiceProcess.stdout.on("data",n=>{
    t+=n.toString();
    let o=t.split(/\r?\n/);
    t=o.pop();
    for(let r of o){
      r=r.trim();
      if(r==="LISTENER_READY"){
        to("[Comnyang] Background voice listener is ready");
      }else if(r.startsWith("LISTENER_ERROR:")){
        Y("[Comnyang] Voice listener error:",r);
      }else if(r.startsWith("UPDATING_CAT_NAME:")||r.startsWith("NAME_ADAPTED:")){
        to("[Comnyang] Voice status:",r);
      }else if(r){
        handleVoiceCommand(r);
      }
    }
  });
  voiceProcess.stderr.on("data",n=>{
    Y("[Comnyang] Voice listener stderr:",n.toString());
  });
  voiceProcess.on("close",n=>{
    to("[Comnyang] Voice listener closed with code",n);
    voiceProcess=null;
  });
}
function stopVoiceAssistant(){
  if(voiceProcess){
    to("[Comnyang] Stopping background voice listener");
    try{voiceProcess.kill();}catch(_){}
    voiceProcess=null;
  }
}
function positionCatTopRight(){
  // Do not force the cat to move to the upper corner.
  // Respect the cat's current position where the user placed it.
  if(!i||i.isDestroyed())return;
}
function handleVoiceCommand(e){
  to("[Comnyang] Heard command:",e);
  let raw=String(e||"").toLowerCase().trim();
  let clean=raw.replace(/[.,\/#!$%\^&\*;:{}=\-_~()?]/g,"").trim();
  let catName=(Z||"comnyang").toLowerCase().trim();
  let safeCatName=catName.replace(/[-[\]{}()*+?.,\\^$|#\s]/g, "\\$&");

  // 1. DISMISS / SLEEP: "bye [cat]", "bye bye [cat]", "go away", "sleep", "hide"
  const dismissRegex=new RegExp("^(?:(?:hey|hi|hello)\\s+)?(?:bye\\s*bye|bye|goodbye|hide|disappear|go\\s*away|sleep)(?:\\s+(?:"+safeCatName+"|cat|bheduu|comnyang|kittu|kitty))?$|^"+safeCatName+"\\s+(?:bye\\s*bye|bye|goodbye|hide|disappear|sleep)$","i");
  if(dismissRegex.test(clean)){
    to("[Comnyang] Match dismiss / hide");
    if(i&&!i.isDestroyed()){
      try{i.webContents.send("play-song",{action:"thinking",query:"Bye bye! 🐾 Call me anytime!"});}catch(_){}
      setTimeout(()=>{
        if(i&&!i.isDestroyed()){
          i.hide();
          to("[Comnyang] Cat hidden from screen (running in background)");
        }
      },700);
    }
    return;
  }

  // 2. SUMMON / APPEAR ALONE: "hey [cat]", "hi [cat]", "hello [cat]", "wake up", "[cat]", "come here", "show"
  const summonRegex=new RegExp("^(?:(?:hey|hi|hello)\\s+)?(?:wake\\s*up|show|come\\s*here|appear)(?:\\s+(?:"+safeCatName+"|cat|bheduu|comnyang|kittu|kitty))?$|^(?:hey|hi|hello)\\s+(?:"+safeCatName+"|cat|bheduu|comnyang|kittu|kitty)$|^"+safeCatName+"$","i");
  if(summonRegex.test(clean)){
    to("[Comnyang] Match summon / appear alone -> trigger top-right & mic listening");
    if(i&&!i.isDestroyed()){
      positionCatTopRight();
      if(!i.isVisible()){
        i.show();
      }
      i.focus();
      kt(i);
      i.webContents.send("play-song",{action:"greet"});
      setTimeout(()=>{
        if(i&&!i.isDestroyed()){
          i.webContents.send("voice-start-record");
        }
      },450);
    }
    return;
  }

  // Check if utterance starts with a wake word prefix (e.g. "hey cat [question]", "[cat] [question]")
  const prefixRegex=new RegExp("^(?:(?:hey|hi|hello)\\s+(?:"+safeCatName+"|cat|bheduu|comnyang|kittu|kitty)|(?:"+safeCatName+"|cat|bheduu|comnyang|kittu|kitty))\\s+","i");
  let coreCommand=clean;
  if(prefixRegex.test(clean)){
    coreCommand=clean.replace(prefixRegex,"").trim();
  }

  // 3. SMART APP / WEB OPENER: "open youtube", "open spotify", etc.
  const openRegex=/^open\s+(.+)$/i;
  const openMatch=coreCommand.match(openRegex);
  if(openMatch){
    const targetToOpen=openMatch[1].trim();
    to("[Comnyang] Match open target:",targetToOpen);
    if(i&&!i.isDestroyed()&&!i.isVisible()){
      i.show();
      i.focus();
    }
    appLauncher.openTarget(targetToOpen,rn).then(res=>{
      to("[Comnyang] App launcher result:",res);
      if(i&&!i.isDestroyed()){
        if(res.mode==="app"){
          i.webContents.send("play-song",{action:"thinking",query:"Opening "+(res.appName||res.target)+" app! 🚀"});
        }else{
          i.webContents.send("play-song",{action:"thinking",query:"Opening "+res.target+" in Brave! 🌐"});
        }
      }
    }).catch(err=>{
      Y("[Comnyang] App launcher error:",err);
    });
    return;
  }

  // 4. STOP / PAUSE MUSIC
  let stopWords=["stop","pause","멈춰","정지","꺼","일시정지","그만"];
  let isStop=stopWords.some(s=>coreCommand===s||coreCommand.startsWith(s)||coreCommand.endsWith(s));
  if(isStop){
    to("[Comnyang] Match stop");
    if(i&&!i.isDestroyed()){
      i.webContents.send("stop-song");
    }
    return;
  }

  // 5. PLAY MUSIC
  let playMatch=coreCommand.match(/^play\s+(.+)$/i);
  let songQuery="";
  if(playMatch){
    songQuery=playMatch[1].trim();
  }else{
    let r=["틀어줘","재생해줘","들려줘","재생","틀어"];
    for(let d of r){
      if(coreCommand.endsWith(d)){
        songQuery=coreCommand.substring(0,coreCommand.length-d.length).trim();
        break;
      }
    }
  }
  if(songQuery){
    to("[Comnyang] Playing song:",songQuery);
    searchAndPlaySong(songQuery);
    return;
  }

  // 6. QUESTION / VOICE PROMPT (e.g. from mic recording or "hey cat [question]")
  // Forward the actual query to the AI agent
  const finalPrompt = coreCommand || clean;
  if(finalPrompt && finalPrompt.length > 1){
    to("[Comnyang] Sending voice prompt to agent:", finalPrompt);
    if(i&&!i.isDestroyed()){
      positionCatTopRight();
      if(!i.isVisible()){
        i.show();
      }
      i.focus();
      kt(i);
      try{i.webContents.send("voice-heard", finalPrompt);}catch(_){}
    }
  }
}
